#!/usr/bin/env bash
set -euo pipefail

# Test: /handoff latency budget + status-bit correctness
# Generated by /qa on 2026-04-24
# Covers: bin/handoff-run.sh (status line), bin/handoff-save-egregore.sh (early exit)

SCRIPT_DIR="$(cd "$(dirname "$0")/../.." && pwd)"
PASS=0
FAIL=0

pass() { PASS=$((PASS + 1)); echo "  ✓ $1"; }
fail() { FAIL=$((FAIL + 1)); echo "  ✗ $1"; [ -n "${2:-}" ] && echo "    $2"; }

millis() { python3 -c 'import time; print(int(time.time()*1000))'; }

echo "Testing: /handoff latency budget + status-bit correctness"
echo ""

# --- 1. handoff-save-egregore.sh early-exit speed ---
echo "# handoff-save-egregore.sh early-exit (sandboxed via --repo-dir)"

# Build a sandbox git repo with no changes and no commits ahead of "origin/develop".
# handoff-save-egregore.sh ignores caller cwd — MUST pass --repo-dir to isolate,
# otherwise the script operates on the real repo and fires real git commits.
TMPD=$(mktemp -d -t handoff-qa-XXXXXX)
SANDBOX="$TMPD/repo"
ORIGIN="$TMPD/origin.git"
trap 'rm -rf "$TMPD"' EXIT
mkdir -p "$SANDBOX"
(
  cd "$SANDBOX"
  git init --quiet --initial-branch=develop
  git config user.email "qa@test.local"
  git config user.name "QA"
  echo "test" > README.md
  printf '%s\n' '{"base_branch":"develop","mode":"local"}' > egregore.json
  git add README.md egregore.json
  git commit -m "init" --quiet
  # Bare origin lives OUTSIDE the sandbox so `git status` stays clean.
  git clone --quiet --bare "$SANDBOX" "$ORIGIN" 2>/dev/null
  git remote add origin "$ORIGIN"
  git fetch origin --quiet 2>/dev/null
)

t1=$(millis)
bash "$SCRIPT_DIR/bin/handoff-save-egregore.sh" "qauser" "timing test" --repo-dir "$SANDBOX" >/dev/null 2>&1
t2=$(millis)
elapsed=$((t2 - t1))
# Threshold is 1000ms to account for bash startup + 3 git invocations on macOS.
# The early-exit path does only local git ops (status/branch/rev-list) — no network.
# A contract on a developer machine, a reading with a ceiling on a shared runner (bin/lib/budget.py).
exit_limit=$(python3 "$SCRIPT_DIR/bin/lib/budget.py" 1000)
if [ "$elapsed" -lt "$exit_limit" ]; then
  pass "early-exit < ${exit_limit}ms (actual: ${elapsed}ms, budget 1000ms)"
else
  fail "early-exit took ${elapsed}ms, expected < ${exit_limit}ms"
fi

# Verify the sandbox didn't accidentally commit anything (early-exit should be a no-op)
sandbox_commits=$(git -C "$SANDBOX" log --oneline 2>/dev/null | wc -l | tr -d ' ')
if [ "$sandbox_commits" = "1" ]; then
  pass "early-exit created no extra commits in sandbox"
else
  fail "early-exit created $((sandbox_commits - 1)) unexpected commit(s) in sandbox"
fi

# --- 2. handoff-save-egregore.sh rejects missing author ---
t1=$(millis)
bash "$SCRIPT_DIR/bin/handoff-save-egregore.sh" >/dev/null 2>&1 && ec=0 || ec=$?
t2=$(millis)
if [ "$ec" = "1" ]; then
  pass "missing author exits 1 (took $((t2 - t1))ms)"
else
  fail "missing author should exit 1, got $ec"
fi

echo ""

# --- 3. handoff-run.sh proposal status: never claim an unattended send ---
echo "# handoff-run.sh status-bit rendering"

# We grep the script source for the specific status-bit construction,
# since running the full orchestrator against the shared memory repo is unsafe.
# The addressed worker may plan, but only an interactive harness can approve
# and dispatch after showing the exact delivery.

if grep -q 'STATUS_BITS+=("notify approval pending")' "$SCRIPT_DIR/bin/handoff-run.sh"; then
  pass "'notify approval pending' bit present"
else
  fail "approval-pending status bit missing from handoff-run.sh"
fi

if grep -q 'notify.sh" plan send' "$SCRIPT_DIR/bin/handoff-run.sh" &&
   grep -q 'notify.sh" plan group' "$SCRIPT_DIR/bin/handoff-run.sh"; then
  pass "handoff worker creates direct or group proposals"
else
  fail "handoff worker no longer creates exact notification proposals"
fi

if ! grep -qE 'notify\.sh" (send|group)' "$SCRIPT_DIR/bin/handoff-run.sh" &&
   ! grep -q 'relayed to group' "$SCRIPT_DIR/bin/handoff-run.sh"; then
  pass "handoff worker cannot dispatch or fall back to group"
else
  fail "handoff worker retains an unattended dispatch or group fallback"
fi

# Proposal creation is unconditional unless explicitly disabled. Recipient
# presence selects proposal kind, never fallback behavior.
if grep -qE 'if \[ "\$NO_NOTIFY" = "0" \]; then' "$SCRIPT_DIR/bin/handoff-run.sh"; then
  pass "proposal branch runs when notifications are enabled"
else
  fail "notification proposal branch is unexpectedly recipient-gated"
fi

echo ""

# --- 4. repo-state.sh latency budget (runs sequentially inside handoff-run.sh) ---
echo "# repo-state.sh — sequential cost inside handoff-run.sh"

# Five interleaved runs of each variant, judged by their medians: one run on
# a shared runner can stall for reasons outside the script (284ms versus
# 396ms on CI), and interleaving gives both variants the same runner load.
# WITH gh pr lookup is manual /handoff outside the hot path; WITHOUT is
# handoff-run.sh via --no-pr, whose PR numbers the detached
# handoff-pr-backfill.sh fills in after.
with_runs=()
no_runs=()
for _ in 1 2 3 4 5; do
  t1=$(millis)
  bash "$SCRIPT_DIR/bin/repo-state.sh" >/dev/null 2>&1 || true
  t2=$(millis)
  with_runs+=($((t2 - t1)))
  t1=$(millis)
  bash "$SCRIPT_DIR/bin/repo-state.sh" --no-pr >/dev/null 2>&1 || true
  t2=$(millis)
  no_runs+=($((t2 - t1)))
done
median() { printf '%s\n' "$@" | sort -n | sed -n "$((($# + 1) / 2))p"; }
with_pr=$(median "${with_runs[@]}")
no_pr=$(median "${no_runs[@]}")
printf "    repo-state.sh (with gh pr lookup): median %dms of %s\n" "$with_pr" "${with_runs[*]}"
printf "    repo-state.sh --no-pr (hot path):  median %dms of %s\n" "$no_pr" "${no_runs[*]}"

# Budgets are contracts on a developer machine and readings with a ceiling on
# a shared runner; bin/lib/budget.py holds the one rule.
hot_limit=$(python3 "$SCRIPT_DIR/bin/lib/budget.py" 800)
if [ "$no_pr" -lt "$hot_limit" ]; then
  pass "repo-state.sh --no-pr < ${hot_limit}ms on hot path (median: ${no_pr}ms, budget 800ms)"
else
  fail "repo-state.sh --no-pr took ${no_pr}ms > ${hot_limit}ms — still too slow on hot path"
fi

# The --no-pr variant must not cost more than the full lookup. This compares
# two variants under the same load, so the runner's speed cancels out and the
# check is not widened on CI; the 50ms margin absorbs timer noise between
# medians that are often equal (70ms versus 71ms on a CI runner, where no PR
# lookup runs).
allowed=$((with_pr + 50))
if [ "$no_pr" -le "$allowed" ]; then
  pass "--no-pr costs no more than the full lookup (median with-pr: ${with_pr}ms, no-pr: ${no_pr}ms, allowed ${allowed}ms)"
else
  fail "--no-pr is slower than the full lookup (median with-pr: ${with_pr}ms, no-pr: ${no_pr}ms, allowed ${allowed}ms)"
fi

# --- 4b. Branch D: today's artifacts query wired correctly ---
echo ""
echo "# handoff-run.sh Branch D (today's artifacts)"

if grep -q "Branch D: Today's artifacts" "$SCRIPT_DIR/bin/handoff-run.sh"; then
  pass "Branch D exists"
else
  fail "Branch D missing — today's artifacts not queried"
fi

# Branch D must be connected-mode gated
if awk '/Branch D: Today/,/^PID_ARTIFACTS=/' "$SCRIPT_DIR/bin/handoff-run.sh" | grep 'MODE.*connected' >/dev/null; then
  pass "Branch D is connected-mode gated"
else
  fail "Branch D missing connected-mode gate"
fi

# Branch B must wait for Branch D (via PID_ARTIFACTS)
if grep -q 'wait "$PID_ARTIFACTS"' "$SCRIPT_DIR/bin/handoff-run.sh"; then
  pass "Branch B waits for Branch D before committing"
else
  fail "Branch B doesn't wait for Branch D — committed file may lack Session Artifacts"
fi

# Result JSON must include artifacts field
if grep -q 'artifacts:\$artifacts' "$SCRIPT_DIR/bin/handoff-run.sh"; then
  pass "Result JSON includes artifacts array"
else
  fail "Result JSON missing artifacts field"
fi

echo ""

# --- 4c. handoff-pr-backfill.sh exists and is executable ---
if [ -x "$SCRIPT_DIR/bin/handoff-pr-backfill.sh" ]; then
  pass "handoff-pr-backfill.sh exists and is executable"
else
  fail "handoff-pr-backfill.sh missing — PR numbers will never backfill"
fi

# handoff-pr-backfill.sh should exit 0 when given a non-existent file (no-op)
if bash "$SCRIPT_DIR/bin/handoff-pr-backfill.sh" /nonexistent.md "topic" >/dev/null 2>&1; then
  pass "handoff-pr-backfill.sh handles missing file gracefully"
else
  fail "handoff-pr-backfill.sh failed on missing file — should exit 0"
fi

# --- 5. handoff-run.sh startup overhead (bash + script parse) ---
t1=$(millis)
bash "$SCRIPT_DIR/bin/handoff-run.sh" --help >/dev/null 2>&1 || true
t2=$(millis)
elapsed=$((t2 - t1))
help_limit=$(python3 "$SCRIPT_DIR/bin/lib/budget.py" 500)
if [ "$elapsed" -lt "$help_limit" ]; then
  pass "handoff-run.sh --help < ${help_limit}ms (actual: ${elapsed}ms, budget 500ms)"
else
  fail "handoff-run.sh --help took ${elapsed}ms > ${help_limit}ms"
fi

echo ""

# --- Summary ---
echo "$PASS passed, $FAIL failed"
[ "$FAIL" -gt 0 ] && exit 1 || exit 0
